<?php
namespace App\Jobs;
use App\Models\Examination;use App\Models\ChoiceOptimizationGoogleFormBatch;use App\Services\ChoiceOptimization\ChoiceOptimizationGoogleFormValidationService;use App\Support\Examinations\ExaminationConnectionManager;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Throwable;
final class ProcessChoiceOptimizationGoogleFormValidation implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=1;public int $timeout=0;public function __construct(public readonly int $examinationId,public readonly int $batchId,public readonly int $actorId){$this->onQueue((string)config('choice-optimization.queue','imports'));}public function handle(ExaminationConnectionManager $connections,ChoiceOptimizationGoogleFormValidationService $service):void{$exam=Examination::query()->findOrFail($this->examinationId);$connections->configure($exam);try{$service->process($this->batchId,$this->actorId);}catch(Throwable $e){ChoiceOptimizationGoogleFormBatch::query()->whereKey($this->batchId)->update(['status'=>'validation_failed','failure_message'=>mb_substr($e->getMessage(),0,65000),'finished_at'=>now()]);throw $e;}finally{$connections->disconnect();}}public function failed(?Throwable $exception):void{report($exception);}}
